class Solution {
public:
    int findTheLongestSubstring(string s) {
        int firstSeen[32];
        for (int i = 0; i < 32; i++) firstSeen[i] = -2;
        firstSeen[0] = -1;
        int vowelBit[26];
        for (int i = 0; i < 26; i++) vowelBit[i] = -1;
        vowelBit[0]  = 0; // a
        vowelBit[4]  = 1; // e
        vowelBit[8]  = 2; // i
        vowelBit[14] = 3; // o
        vowelBit[20] = 4; // u
        int mask = 0, best = 0;
        int n = (int)s.size();
        for (int i = 0; i < n; i++) {
            int b = vowelBit[s[i] - 'a'];
            if (b >= 0) mask ^= (1 << b);
            if (firstSeen[mask] == -2) {
                firstSeen[mask] = i;
            } else {
                int len = i - firstSeen[mask];
                if (len > best) best = len;
            }
        }
        return best;
    }
};
